<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Demo Gestor de Tareas</title><link rel="stylesheet" href="demo-style.css?v=5"></head><body><nav class="demo-nav"><div class="demo-nav-inner"><a class="brand" href="../index.php#proyectos">← Volver al portafolio</a><a class="btn primary" href="#">Demo local</a></div></nav><main class="wrap"><section class="hero"><div><span class="kicker">PHP + MySQL</span><h1>Gestor de Tareas</h1><p>Demo visual de una aplicación para registrar, listar y administrar tareas académicas con estados de avance.</p></div><div class="panel"><h2>Nueva tarea</h2><input id="task" placeholder="Ej: Subir portafolio a FileZilla"><button class="btn primary" onclick="addTask()" style="margin-top:12px">Agregar tarea</button></div></section><section class="panel"><h2>Listado de tareas</h2><div id="list" class="grid"></div></section></main><script>const seed=['Revisar conexión MySQL','Corregir rutas CSS','Probar login administrativo'];const list=document.getElementById('list');function render(arr){list.innerHTML=arr.map((t,i)=>`<article class="card"><span class="pill">Tarea ${i+1}</span><h3>${t}</h3><p class="muted">Estado: pendiente de revisión.</p></article>`).join('')}let tasks=[...seed];function addTask(){const v=task.value.trim();if(!v)return;tasks.unshift(v);task.value='';render(tasks)}render(tasks);</script></body></html>
